{
  "spec": "Build a 32-bit ripple-carry adder (top_module) using two provided 16-bit adders (add16). Each add16 is constructed from 16 instances of a 1-bit full adder (add1) that you must write. The top_module takes two 32-bit inputs a and b and produces a 32-bit sum. The lower add16 handles bits 0-15 with carry-in tied to 0; its carry-out feeds the upper add16's carry-in for bits 16-31. The upper add16's carry-out is unused. You must implement add1 (sum = a^b^cin, cout = majority) and wire the two add16 instances in top_module.",
  "given_sv": "module add16(input [15:0] a, input [15:0] b, input cin, output [15:0] sum, output cout);
  wire [15:0] carry;
  genvar i;
  generate for (i=0; i<16; i=i+1) begin : stage
    wire c_in = (i==0) ? cin : carry[i-1];
    wire c_out;
    add1 u_add1 (.a(a[i]), .b(b[i]), .cin(c_in), .sum(sum[i]), .cout(c_out));
    assign carry[i] = c_out;
  end
  assign cout = carry[15];
endmodule",
  "ref_sv": "module RefModule(input [31:0] a, input [31:0] b, output [31:0] sum);
  assign sum = a + b;
endmodule",
  "solution_sv": "module add1(input a, input b, input cin, output sum, output cout);
  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);
endmodule

module top_module(input [31:0] a, input [31:0] b, output [31:0] sum);
  wire carry_low;
  add16 lower (.a(a[15:0]), .b(b[15:0]), .cin(1'b0), .sum(sum[15:0]), .cout(carry_low));
  add16 upper (.a(a[31:16]), .b(b[31:16]), .cin(carry_low), .sum(sum[31:16]), .cout());
endmodule",
  "directed": [{"a": 0, "b": 0}, {"a": 5, "b": 3}, {"a": 65535, "b": 1}, {"a": 4294901760, "b": 65535}, {"a": 4294967295, "b": 1}, {"a": 305419896, "b": 2271560481}],
  "hints": {"L0": "A 1-bit full adder computes sum = a XOR b XOR cin and carry-out = majority(a,b,cin).", "L3": "Instantiate two add16 modules: lower takes a[15:0], b[15:0], cin=0; its cout connects to upper's cin. Upper takes a[31:16], b[31:16]; its cout is left open. Concatenate lower.sum and upper.sum to form the 32-bit sum."},
  "common_mistakes": ["Forgetting to tie the lower add16's cin to 0.", "Not connecting the lower add16's cout to the upper add16's cin.", "Reversing the bit slices (e.g., using a[31:16] for the lower adder).", "Implementing add1 incorrectly, such as missing a term in the carry-out expression."]
}

